import zipfile
with zipfile.ZipFile('/root/project_proposal_ready.hwpx', 'r') as zin:
    for name in zin.namelist():
        if name.endswith('.xml'):
            content = zin.read(name).decode('utf-8')
            count_2026_07_15 = content.count('2026-07-15')
            count_placeholders = content.count('{{')
            print(f'{name}: 2026-07-15 count={count_2026_07_15}, placeholders={{count={count_placeholders}}}')
            if count_placeholders > 0:
                for line in content.split('\n'):
                    if '{{' in line:
                        print(f'  {line}')
"

