arguments.command:
cd /tmp/hwpx_work && python3 -c "
import zipfile
with zipfile.ZipFile('/root/project_proposal_ready.hwpx', 'r') as zin:
    for name in zin.namelist():
        if name.endswith('.xml'):
            content = zin.read(name).decode('utf-8')
            # Check for budget normalized (no commas)
            if '₩450000000' in content:
                print(f'{name}: Budget normalized correctly (₩450000000)')
            # Check for month spans
            if '개월' in content:
                for line in content.split('\n'):
                    if '개월' in line:
                        print(f'{name}: Phase with month span: {line[:200]}')
            # Check for all key values
            for key in ['스마트 워크플로우 자동화', '디지털 혁신실', '2026-08-01', '2027-01-31', '최수민 차장']:
                if key in content:
                    print(f'{name}: Contains \"{key}\"')
"

